run_python({"source": "import bpy
from mathutils import Vector

crate = bpy.data.objects["Crate"]
me = crate.data

def classify(n):
    n = Vector(n)
    comps = sorted((abs(c) for c in n), reverse=True)
    if comps[0] > 0.9:
        return "main"
    if comps[2] > 0.4:
        return "corner"
    return "strip"

# name main faces by dominant axis+sign
def main_name(n):
    n = Vector(n)
    ax = max(range(3), key=lambda i: abs(n[i]))
    sign = "+" if n[ax] > 0 else "-"
    return "XYZ"[ax] + sign

# edge -> faces
edge_faces = {}
for p in me.polygons:
    for ek in p.edge_keys:
        edge_faces.setdefault(ek, []).append(p.index)

def neighbors(pi):
    out = []
    for ek in me.polygons[pi].edge_keys:
        for q in edge_faces[ek]:
            if q != pi:
                out.append(q)
    return out

mains = {}   # name -> face index
strips = []  # face indices
corners = [] # face indices
for p in me.polygons:
    c = classify(p.normal)
    if c == "main":
        mains[main_name(p.normal)] = p.index
    elif c == "strip":
        strips.append(p.index)
    else:
        corners.append(p.index)

print("mains:", mains)
print("strips:", strips)
print("corners:", corners)

# identify each strip by its 2 main faces
strip_mains = {}
for s in strips:
    ns = [q for q in neighbors(s) if q in mains.values()]
    names = tuple(sorted(main_name(me.polygons[q].normal) for q in ns))
    strip_mains[s] = names
    print("strip", s, "->", names)

# identify each corner by its 3 strips
corner_strips = {}
for c in corners:
    ns = [q for q in neighbors(c) if q in strips]
    corner_strips[c] = ns
    print("corner", c, "-> strips", ns)
"})

