run_python({"source": "import bpy, bmesh
from collections import deque

crate = bpy.data.objects["Crate"]
mesh = crate.data
bm = bmesh.new()
bm.from_mesh(mesh)
bm.faces.ensure_lookup_table()
bm.edges.ensure_lookup_table()

# build face adjacency via non-seam edges
face_edges = {}
for f in bm.faces:
    for e in f.edges:
        face_edges.setdefault(e.index, []).append(f.index)

adj = {f.index: set() for f in bm.faces}
for e in bm.edges:
    if e.seam:
        continue
    fs = face_edges.get(e.index, [])
    for a in fs:
        for b in fs:
            if a != b:
                adj[a].add(b)

seen = set()
islands = []
for f in bm.faces:
    if f.index in seen:
        continue
    comp = []
    q = deque([f.index])
    seen.add(f.index)
    while q:
        cur = q.popleft()
        comp.append(cur)
        for nb in adj[cur]:
            if nb not in seen:
                seen.add(nb)
                q.append(nb)
    islands.append(comp)

print("islands from seam structure:", len(islands))
for i, comp in enumerate(islands):
    # classify faces by normal
    from mathutils import Vector
    normals = {}
    for fi in comp:
        n = bm.faces[fi].normal
        ax = max(range(3), key=lambda k: abs(n[k]))
        key = ('X' if ax==0 else 'Y' if ax==1 else 'Z') + ('+' if n[ax]>0 else '-')
        normals[key] = normals.get(key, 0) + 1
    print(f"  island {i}: {len(comp)} faces, {normals}")
bm.free()
