run_python({"object_name": "Crate", "plan_step": 3, "source": "import bpy, bmesh
from blended.ops import unwrap_uvs

crate = bpy.data.objects['Crate']

while crate.data.uv_layers:
    crate.data.uv_layers.remove(crate.data.uv_layers[0])

bpy.context.view_layer.objects.active = crate
bpy.ops.object.mode_set(mode='OBJECT')

mesh = crate.data
bm = bmesh.new()
bm.from_mesh(mesh)
bm.faces.ensure_lookup_table()

AXIS_DOMINANCE_THRESHOLD = 0.999

def classify(face):
    n = face.normal
    if abs(n.z) > AXIS_DOMINANCE_THRESHOLD:
        return ('Z', 1 if n.z > 0 else -1)
    if abs(n.x) > AXIS_DOMINANCE_THRESHOLD:
        return ('X', 1 if n.x > 0 else -1)
    if abs(n.y) > AXIS_DOMINANCE_THRESHOLD:
        return ('Y', 1 if n.y > 0 else -1)
    return None

groups = {f.index: classify(f) for f in bm.faces}

for e in bm.edges:
    e.seam = False

seam_count = 0
for e in bm.edges:
    linked = e.link_faces
    if len(linked) != 2:
        continue
    g0 = groups[linked[0].index]
    g1 = groups[linked[1].index]
    if g0 != g1:
        e.seam = True
        seam_count += 1

bm.to_mesh(mesh)
bm.free()
mesh.update()

print('main face groups present:', set(v for v in groups.values() if v is not None))
print('seam edges marked:', seam_count)

report = unwrap_uvs(crate, method='ANGLE_BASED')
print(report)
"})
